bitfield.description:
Hardware Receive timestamp select (RX_TIMESTAMP);
0 = sample realtime free running microsecond counter;
1 = sample Access Manager TSF

state status latched in error_irq
cleared when writing any value to RX_ERROR_IRQ_STATUS_CAUSE_WROPT

same bit-mapping as RX_STATE_STATUS:
[28]    = rx_path_en;
[27]    = rx_scrpt_busy;
[26:24] = enc_state;
[23]    = 1'b0;
[22:20] = addr_srch_ocp_state;
[19]    = rx_bb_if_state;
[18:16] = addr_srch_main_state;
[15]    = 1'b0;
[14:12] = parser_state;
[11: 8] = adu_mmu_ctrl_state;
[ 7: 4] = adu_amsdu_parser_state;
[ 3: 0] = rx_mng_state;

Report of drop_status from rx_manager (raw status - not including the mask or ovrd: rx_mng_drop_dynamic_mask_wropt / rx_mng_drop_ovrd_wropt):

assign drop_status[0] = rx_last_no_data_latch ? 1'b0 : ~frame_delivered_to_sw ;
assign drop_status[1] = (rx_fcs_bad & rx_mpdu_done) & ~(abort_sticky | fifo_overflow_sticky); // drop by fcs result only when it is valid and only for join at mpdu_done (fcs=pass for push, not valid yet)
assign drop_status[2] = key_id_mismatch | key_ptr_too_low;
assign drop_status[3] = adu_frm_done_status[0]; // memory access error (adu fd_range_err_during_frm)
assign drop_status[4] = abort_sticky & ~(bet_abort_cng_mode_latch | bet_suspend_decision | rx_last_no_data_latch) ;
assign drop_status[5] = adu_frm_done_status[2]; // mpdu_too_long (adu fd_payload_gt_max)
assign drop_status[6] = fifo_overflow_sticky;
assign drop_status[7] = 1'b0; // place holder for future
